(5609120, 813286, 83313, '<td valign="top">A bit dark, but hey, it''s a midsummer night! The clouds look pretty cool in this shot.</td>', 'A bit dark, but hey, it''s a midsummer night! The clouds look pretty cool in this shot.', '2009-08-12 13:48:43.000000', NULL, 1),
(5609121, 813303, 83313, '<td valign="top">Is this what happens when the old girlfriends finally catch up with you? I might''ve given it a bit more contrast and sharpness, but that''s just a personal preference.</td>', 'Is this what happens when the old girlfriends finally catch up with you? I might''ve given it a bit more contrast and sharpness, but that''s just a personal preference.', '2009-08-12 13:51:19.000000', NULL, 1),
(5609122, 812607, 83313, '<td valign="top">Nice rusty-crusty. Maybe cropped a touch too tight at the bottom for my preference, but that''s a nitpick.</td>', 'Nice rusty-crusty. Maybe cropped a touch too tight at the bottom for my preference, but that''s a nitpick.', '2009-08-12 13:52:30.000000', NULL, 1),
(5609123, 812435, 92577, '<td valign="top">a few spots and specks to be cloned out after the challenge but apart from that this is simply wonderful. Like a water color painting.</td>', 'a few spots and specks to be cloned out after the challenge but apart from that this is simply wonderful. Like a water color painting.', '2009-08-12 13:52:36.000000', NULL, 1),
