(5609968, 813029, 49220, '<td valign="top">Cut subject and good depth of field.  The extension cords are a bit distracting unfortunately.</td>', 'Cut subject and good depth of field.  The extension cords are a bit distracting unfortunately.', '2009-08-13 04:44:35.000000', NULL, 1),
(5609969, 813047, 49220, '<td valign="top">The rotation is distracting for me, even if it was intentional.</td>', 'The rotation is distracting for me, even if it was intentional.', '2009-08-13 04:45:35.000000', NULL, 1),
(5609970, 812676, 49220, '<td valign="top">Whatever that is, it looks cool.  It''s a shame the wind was blowing the trees so much, cause it would have been even cooler if the leaves were still in focus, but there''s not much you can do about that.  I really like the shot, although I''m not sure if the main focus is really the title.</td>', 'Whatever that is, it looks cool.  It''s a shame the wind was blowing the trees so much, cause it would have been even cooler if the leaves were still in focus, but there''s not much you can do about that.  I really like the shot, although I''m not sure if the main focus is really the title.', '2009-08-13 04:47:32.000000', NULL, 1),
(5609971, 813013, 49220, '<td valign="top">I''m not a big fan of having the motion blur on the subjects like that while the background stays in focus, but it does match the title decently.  I''m wondering if it would have worked better to pan with the people.</td>', 'I''m not a big fan of having the motion blur on the subjects like that while the background stays in focus, but it does match the title decently.  I''m wondering if it would have worked better to pan with the people.', '2009-08-13 04:49:16.000000', NULL, 1),
(5609972, 813088, 49220, '<td valign="top">Not quite sure how this matches the title, but still a lovely composition.  I might like it a tiny bit more if it was rotated slightly CCW.</td>', 'Not quite sure how this matches the title, but still a lovely composition.  I might like it a tiny bit more if it was rotated slightly CCW.', '2009-08-13 04:51:08.000000', NULL, 1),
(5609973, 813133, 49220, '<td valign="top">Lol, I love this picture.  How much was that pig squirming.  Good job keeping the subject in focus while panning.</td>', 'Lol, I love this picture.  How much was that pig squirming.  Good job keeping the subject in focus while panning.', '2009-08-13 04:52:22.000000', NULL, 1),
(5609974, 813080, 49220, '<td valign="top">I''m not sure if I would like this with more or less depth of field, but it seems somewhere in between what would have looked best, since the back cans are neither extremely blurry nor in focus.</td>', 'I''m not sure if I would like this with more or less depth of field, but it seems somewhere in between what would have looked best, since the back cans are neither extremely blurry nor in focus.', '2009-08-13 04:54:18.000000', NULL, 1),
(5609975, 813098, 49220, '<td valign="top">Very nice use of the trees for the framing of this shot.  It seems a bit grainy, and the moon is too blown out.  I wonder what it would have looked like with a faster shutter speed to get more detail on the moon while still keeping the silhouettes.  Still, I like the simple but effective composition.</td>', 'Very nice use of the trees for the framing of this shot.  It seems a bit grainy, and the moon is too blown out.  I wonder what it would have looked like with a faster shutter speed to get more detail on the moon while still keeping the silhouettes.  Still, I like the simple but effective composition.', '2009-08-13 04:57:55.000000', NULL, 1),
(5609976, 813354, 49220, '<td valign="top">Nice color in the sky.  I might like it a bit better to have taken this from a longer distance away (or a wider crop) to get a bit more of the beautiful background scenery.</td>', 'Nice color in the sky.  I might like it a bit better to have taken this from a longer distance away (or a wider crop) to get a bit more of the beautiful background scenery.', '2009-08-13 04:59:28.000000', NULL, 1),
(5609977, 813068, 49220, '<td valign="top">I really like the contrast you got without anything getting too blown out.  Great color on the building.</td>', 'I really like the contrast you got without anything getting too blown out.  Great color on the building.', '2009-08-13 05:00:12.000000', NULL, 1),
(5609978, 813297, 49220, '<td valign="top">Not sure I get how this matches the title... maybe the dice just confused me.</td>', 'Not sure I get how this matches the title... maybe the dice just confused me.', '2009-08-13 05:00:56.000000', NULL, 1),
(5609979, 813318, 49220, '<td valign="top">Nice picture, but it seems a bit soft (maybe that''s not quit the right word, but I can''t think of anything better right now) for my taste.</td>', 'Nice picture, but it seems a bit soft (maybe that''s not quit the right word, but I can''t think of anything better right now) for my taste.', '2009-08-13 05:02:24.000000', NULL, 1),
(5609982, 812571, 49220, '<td valign="top">Nice picture, although I''m not sure this best illustrates the mirror concept.  Might have been more apt to have taken it closer to the pier so you could see it in the reflection (although it''s hard to tell if you would have had enough light for that).</td>', 'Nice picture, although I''m not sure this best illustrates the mirror concept.  Might have been more apt to have taken it closer to the pier so you could see it in the reflection (although it''s hard to tell if you would have had enough light for that).', '2009-08-13 05:05:39.000000', NULL, 1),
(5609984, 813155, 49220, '<td valign="top">Interesting repetition in the picture, but kind of boring.</td>', 'Interesting repetition in the picture, but kind of boring.', '2009-08-13 05:06:51.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5609985, 813211, 49220, '<td valign="top">I like how the motion is captured so cleanly...  and the tongue hanging out.</td>', 'I like how the motion is captured so cleanly...  and the tongue hanging out.', '2009-08-13 05:08:12.000000', NULL, 1),
(5609986, 812682, 49220, '<td valign="top">While the hand looks great, whatever is on the left had side is quit distracting to my eye.  I like the good color and contrast though.</td>', 'While the hand looks great, whatever is on the left had side is quit distracting to my eye.  I like the good color and contrast though.', '2009-08-13 05:09:48.000000', NULL, 1),
(5609987, 812764, 49220, '<td valign="top">It seems a bit too close to the gears.  I would like to see more of the clock, and maybe not from on top quit so much.  Also, it would have been nice to have had a fast enough shutter speed to stop the motion.</td>', 'It seems a bit too close to the gears.  I would like to see more of the clock, and maybe not from on top quit so much.  Also, it would have been nice to have had a fast enough shutter speed to stop the motion.', '2009-08-13 05:13:07.000000', NULL, 1),
(5609988, 813173, 49220, '<td valign="top">Very cool shot, and a beautiful location.  While it might have been better to emphasize the horse as the subject with a closer crop like you have done, I would also love to see the rest of those mountains.</td>', 'Very cool shot, and a beautiful location.  While it might have been better to emphasize the horse as the subject with a closer crop like you have done, I would also love to see the rest of those mountains.', '2009-08-13 05:14:40.000000', NULL, 1),
(5609989, 812556, 49220, '<td valign="top">It''s a shame that some of the flower is out of focus, otherwise I really like it.</td>', 'It''s a shame that some of the flower is out of focus, otherwise I really like it.', '2009-08-13 05:15:38.000000', NULL, 1),
(5609990, 812129, 49220, '<td valign="top">Lol, I like the props you were able to pull together.  It would have been nice to have a bit more shadows to add some further depth to the shot.  It almost seems too bright and evenly lit to be outdoors.</td>', 'Lol, I like the props you were able to pull together.  It would have been nice to have a bit more shadows to add some further depth to the shot.  It almost seems too bright and evenly lit to be outdoors.', '2009-08-13 05:18:45.000000', NULL, 1),
(5609992, 812862, 49220, '<td valign="top">Very nice subject, and I love the light streaming out of the door and casting the shadow of the man.  It''s a shame there wasn''t a little bit more light to get some more highlights and details out of that beautiful wall, although on second thought it might have been even cooler if the wall was hardly lit so that the light source from the door was the only one.  I''m a bit torn.</td>', 'Very nice subject, and I love the light streaming out of the door and casting the shadow of the man.  It''s a shame there wasn''t a little bit more light to get some more highlights and details out of that beautiful wall, although on second thought it might have been even cooler if the wall was hardly lit so that the light source from the door was the only one.  I''m a bit torn.', '2009-08-13 05:21:48.000000', NULL, 1),
(5609994, 813299, 14212, '<td valign="top">Something about this shot reminds me of my childhood. I can''t figure out what though. I''d love to get a copy from you if you don''t mind. Thanks</td>', 'Something about this shot reminds me of my childhood. I can''t figure out what though. I''d love to get a copy from you if you don''t mind. Thanks', '2009-08-13 05:23:38.000000', NULL, 1),
(5609995, 812986, 49220, '<td valign="top">Maybe I''m just being a silly American, but I wonder if something iconic like Big Ben would be a more recognizable subject as something from London.  Still, I like the composition and the use of a mild sepia tone while keeping the color in the flag.  It''s a shame the wind wasn''t expanding the flag a bit more.  I''m curious why the cables seems so blurry when the glass pods are so in focus, and why there is nothing in the background, considering the sense of perspective I get from the building doesn''t look like you are pointing into the sky.</td>', 'Maybe I''m just being a silly American, but I wonder if something iconic like Big Ben would be a more recognizable subject as something from London.  Still, I like the composition and the use of a mild sepia tone while keeping the color in the flag.  It''s a shame the wind wasn''t expanding the flag a bit more.  I''m curious why the cables seems so blurry when the glass pods are so in focus, and why there is nothing in the background, considering the sense of perspective I get from the building doesn''t look like you are pointing into the sky.', '2009-08-13 05:28:49.000000', NULL, 1),
(5609996, 812531, 49220, '<td valign="top">Very nice.   It seems you managed to catch it right as it was struck, which is impressive to me.</td>', 'Very nice.   It seems you managed to catch it right as it was struck, which is impressive to me.', '2009-08-13 05:29:50.000000', NULL, 1),
(5609998, 813303, 49220, '<td valign="top">I''m no gun expert, but is that really a sniper riffle?  It seems more of an assault rifle, especially with that scope on it and the side mounted light, although it is a bit hard to tell looking right down the barrel.  I think I would have tried to keep her in focus.</td>', 'I''m no gun expert, but is that really a sniper riffle?  It seems more of an assault rifle, especially with that scope on it and the side mounted light, although it is a bit hard to tell looking right down the barrel.  I think I would have tried to keep her in focus.', '2009-08-13 05:32:20.000000', NULL, 1),
(5609999, 812354, 49220, '<td valign="top">I love the perspective and the reflection.  It''s a shame there were no interesting clouds to add something more to the sky.</td>', 'I love the perspective and the reflection.  It''s a shame there were no interesting clouds to add something more to the sky.', '2009-08-13 05:33:24.000000', NULL, 1),
(5610000, 813099, 49220, '<td valign="top">Nice dune, although it seems a bit dull without the sky for contrasting color.</td>', 'Nice dune, although it seems a bit dull without the sky for contrasting color.', '2009-08-13 05:34:27.000000', NULL, 1),
(5610001, 812248, 49220, '<td valign="top">I really like the reflection and the color.</td>', 'I really like the reflection and the color.', '2009-08-13 05:35:20.000000', NULL, 1),
(5610002, 813225, 49220, '<td valign="top">A little bit dark for my taste (both in lighting/contrast and expression - clowns are creepy enough as it is, although I''m not familiar with that book, so maybe it is more apt).  I might have preferred a crop that was a bit more square with less of the black on the sides.</td>', 'A little bit dark for my taste (both in lighting/contrast and expression - clowns are creepy enough as it is, although I''m not familiar with that book, so maybe it is more apt).  I might have preferred a crop that was a bit more square with less of the black on the sides.', '2009-08-13 05:38:06.000000', NULL, 1),
(5610004, 813216, 49220, '<td valign="top">Lol.  I''m not sure I like the face chopped off like that.  Might have been more effective if he was screaming into someone else''s ear who had their hands covering their ears.</td>', 'Lol.  I''m not sure I like the face chopped off like that.  Might have been more effective if he was screaming into someone else''s ear who had their hands covering their ears.', '2009-08-13 05:40:11.000000', NULL, 1),
(5610006, 812547, 49220, '<td valign="top">The shot seems very busy (hard to figure out the subject/focus).  It also seems very flat on contrast, although I''m sure all those lights didn''t really help that.</td>', 'The shot seems very busy (hard to figure out the subject/focus).  It also seems very flat on contrast, although I''m sure all those lights didn''t really help that.', '2009-08-13 05:41:52.000000', NULL, 1),
(5610008, 813403, 49220, '<td valign="top">Nice perspective and a great subject to use for the title.  I also like the  clouds.</td>', 'Nice perspective and a great subject to use for the title.  I also like the  clouds.', '2009-08-13 05:42:58.000000', NULL, 1),
(5610009, 813382, 49220, '<td valign="top">Is that really smoke?  It seems a bit too orderly and perfect in the loops for some reason.  Still, I like the blue on black like that.</td>', 'Is that really smoke?  It seems a bit too orderly and perfect in the loops for some reason.  Still, I like the blue on black like that.', '2009-08-13 05:44:29.000000', NULL, 1),
(5610010, 813070, 49220, '<td valign="top">A bit flat on the lighting/contrast, although the kid is cute.  Background is a bit distracting for being so close up on the face.</td>', 'A bit flat on the lighting/contrast, although the kid is cute.  Background is a bit distracting for being so close up on the face.', '2009-08-13 05:45:55.000000', NULL, 1),
(5610011, 812763, 49220, '<td valign="top">Very nice contrast, although I''m not sure I''d call this a bleak house particularly.  Still, I really like the shot.</td>', 'Very nice contrast, although I''m not sure I''d call this a bleak house particularly.  Still, I really like the shot.', '2009-08-13 05:47:11.000000', NULL, 1),
(5610018, 812472, 90624, '<td valign="top">No don''t do it!!! Some Bunny will love you!</td>', 'No don''t do it!!! Some Bunny will love you!', '2009-08-13 06:31:59.000000', NULL, 1),
(5610019, 813270, 90624, '<td valign="top">Oh please tell us where this is!!</td>', 'Oh please tell us where this is!!', '2009-08-13 06:34:34.000000', NULL, 1),
(5610020, 812999, 90624, '<td valign="top">please explain the treatment to this photo I love the painted effect of it.</td>', 'please explain the treatment to this photo I love the painted effect of it.', '2009-08-13 06:38:43.000000', NULL, 1),
(5610047, 813258, 91716, '<td valign="top">Such a common idea..</td>', 'Such a common idea..', '2009-08-13 07:22:40.000000', NULL, 1),
(5610176, 813047, 15711, '<td valign="top">Really nice - too bad we couldn''t have advanced editing.  This is probably the best considering the limitations. 8</td>', 'Really nice - too bad we couldn''t have advanced editing.  This is probably the best considering the limitations. 8', '2009-08-13 10:11:43.000000', NULL, 1),
(5610178, 813099, 15711, '<td valign="top">Really nice.  Probably the best I''ve seen yet.</td>', 'Really nice.  Probably the best I''ve seen yet.', '2009-08-13 10:13:10.000000', NULL, 1),
(5610180, 812986, 15711, '<td valign="top">I like this a lot.  Great editing, considering the constraints of basic editing.</td>', 'I like this a lot.  Great editing, considering the constraints of basic editing.', '2009-08-13 10:13:49.000000', NULL, 1),
(5610182, 813225, 15711, '<td valign="top">GOOD GRIEF!!  This reiterates my terror of clowns. YIKES  7</td>', 'GOOD GRIEF!!  This reiterates my terror of clowns. YIKES  7', '2009-08-13 10:14:46.000000', NULL, 1),
(5610195, 812999, 54728, '<td valign="top">A little too processed for my taste.  It''s a beautiful image that loses much of its effect because the intense hipass stuff distracts me from the actual content.</td>', 'A little too processed for my taste.  It''s a beautiful image that loses much of its effect because the intense hipass stuff distracts me from the actual content.', '2009-08-13 10:29:10.000000', NULL, 1),
(5610196, 812684, 54728, '<td valign="top">Splendid!</td>', 'Splendid!', '2009-08-13 10:30:27.000000', NULL, 1),
(5610229, 813251, 24389, '<td valign="top">so far this is my fav of this challenge. Nice job!</td>', 'so far this is my fav of this challenge. Nice job!', '2009-08-13 11:08:25.000000', NULL, 1),
(5610265, 813241, 105697, '<td valign="top">Beautiful image, I really had to stop and simply <i>enjoy </i>this one for a while. Thanks and best wishes of success to you!</td>', 'Beautiful image, I really had to stop and simply enjoy this one for a while. Thanks and best wishes of success to you!', '2009-08-13 11:52:04.000000', NULL, 1),
(5610269, 812132, 105697, '<td valign="top">Dazzling, I really enjoyed your photo! It really works well on the title you picked. Success to you!</td>', 'Dazzling, I really enjoyed your photo! It really works well on the title you picked. Success to you!', '2009-08-13 11:54:50.000000', NULL, 1),
(5610276, 813251, 105697, '<td valign="top">I like this better than any shot from the ScoobyDoo movies! Well done!</td>', 'I like this better than any shot from the ScoobyDoo movies! Well done!', '2009-08-13 11:58:48.000000', NULL, 1),
(5610279, 813132, 105697, '<td valign="top">I really like that "Jonathan" here seems to have more personallity than your average seagull. You caught that well! Thanks!</td>', 'I really like that "Jonathan" here seems to have more personallity than your average seagull. You caught that well! Thanks!', '2009-08-13 12:00:06.000000', NULL, 1),
(5610280, 812838, 105697, '<td valign="top">Thanks for a really fine photo! Success to you!</td>', 'Thanks for a really fine photo! Success to you!', '2009-08-13 12:00:54.000000', NULL, 1),
(5610281, 812790, 105697, '<td valign="top">The child may not be in an actual corn field, but it is sure a great photo. Success to you!</td>', 'The child may not be in an actual corn field, but it is sure a great photo. Success to you!', '2009-08-13 12:02:44.000000', NULL, 1),
(5610283, 813047, 105697, '<td valign="top">You photo just begs one to enter into "The Mist". Thanks!</td>', 'You photo just begs one to enter into "The Mist". Thanks!', '2009-08-13 12:03:46.000000', NULL, 1),
(5610286, 812351, 105697, '<td valign="top">Ooooh, this changes the image of that innocent children''s story! Great photo, one of the best pics of a spider ever done! <b>Success</b> to you!</td>', 'Ooooh, this changes the image of that innocent children''s story! Great photo, one of the best pics of a spider ever done! Success to you!', '2009-08-13 12:11:05.000000', NULL, 1),
(5610345, 813369, 64795, '<td valign="top">This one is a little bit blurry and just not the most interesting photo.  Try a different angle.</td>', 'This one is a little bit blurry and just not the most interesting photo.  Try a different angle.', '2009-08-13 12:53:49.000000', NULL, 1),
(5610350, 812564, 64795, '<td valign="top">I am usually a fan of thick borders but this one distracts from the photo.  Nice location!</td>', 'I am usually a fan of thick borders but this one distracts from the photo.  Nice location!', '2009-08-13 12:56:30.000000', NULL, 1),
(5610352, 813173, 64795, '<td valign="top">I really like this!</td>', 'I really like this!', '2009-08-13 12:56:59.000000', NULL, 1),
(5610376, 813098, 99256, '<td valign="top">New Moon means no moon though.  ETA more specificaly shadowed moon.  It''s still there and you can see it but it''s not bright like that.</td>', 'New Moon means no moon though.  ETA more specificaly shadowed moon.  It''s still there and you can see it but it''s not bright like that.', '2009-08-13 13:10:34.000000', NULL, 1),
(5610411, 813120, 99506, '<td valign="top">Seems a bit like a snapshot, not very interesting and a little bland.<br/>For me the focal point of the image is that part that is obscuring the cat''s mouth and is rather distracting.<br/>I think an image of the Cat being cradled in someones arms may have made an interesting shot and still applicable to the title.<br/>Overall there are just too many distractions and it''s not very interesting so it''s a 4 from me.</td>', 'Seems a bit like a snapshot, not very interesting and a little bland.For me the focal point of the image is that part that is obscuring the cat''s mouth and is rather distracting.I think an image of the Cat being cradled in someones arms may have made an interesting shot and still applicable to the title.Overall there are just too many distractions and it''s not very interesting so it''s a 4 from me.', '2009-08-13 13:38:02.000000', NULL, 1),
(5610412, 813418, 99506, '<td valign="top">Well the image certainly meets the challenge very well.<br/>Something about the table being set for a left hander just makes it odd to look at, not that there is anything wrong with left handed people of course, my own son is one.<br/> <br/>In terms of image quality it has a real snapshot feel, a bit flat and uninteresting, with the top left hand corner being a a distration in my opinion.<br/> <br/>There is also a depth of field problem with the foreground appearing to be out of focus.<br/> <br/>To improve I would have possible put a dark table cloth under the plate, stood further back to take the shot and avoided cropping out the handle of the knife.<br/> <br/>Sorry to be harsh but I''m scoring it 4/10</td>', 'Well the image certainly meets the challenge very well.Something about the table being set for a left hander just makes it odd to look at, not that there is anything wrong with left handed people of course, my own son is one. In terms of image quality it has a real snapshot feel, a bit flat and uninteresting, with the top left hand corner being a a distration in my opinion. There is also a depth of field problem with the foreground appearing to be out of focus. To improve I would have possible put a dark table cloth under the plate, stood further back to take the shot and avoided cropping out the handle of the knife. Sorry to be harsh but I''m scoring it 4/10', '2009-08-13 13:38:11.000000', NULL, 1),
(5610425, 813321, 99506, '<td valign="top">I like the idea but the image seems to lack something.<br/>I think the lack of focus compared to other water drops that we see on here makes it seem a little flat and uninteresting.<br/> <br/>I think that more focus possibly on the refracted image in the water would give it more depth and interest.<br/> <br/>Sorry to be harsh but I''m voting a 4</td>', 'I like the idea but the image seems to lack something.I think the lack of focus compared to other water drops that we see on here makes it seem a little flat and uninteresting. I think that more focus possibly on the refracted image in the water would give it more depth and interest. Sorry to be harsh but I''m voting a 4', '2009-08-13 14:12:37.000000', NULL, 1),
(5610473, 813211, 107410, '<td valign="top">What''s with the ghosting in this image?</td>', 'What''s with the ghosting in this image?', '2009-08-13 14:41:40.000000', NULL, 1),
(5610474, 812453, 81082, '<td valign="top">Great subject, clouds... just could have been taken better. Just my opinion!</td>', 'Great subject, clouds... just could have been taken better. Just my opinion!', '2009-08-13 14:43:42.000000', NULL, 1),
(5610477, 813212, 107410, '<td valign="top">Great capture! Very very sharp!</td>', 'Great capture! Very very sharp!', '2009-08-13 14:44:23.000000', NULL, 1),
(5610479, 813135, 107410, '<td valign="top">That foot is in a terrible place!</td>', 'That foot is in a terrible place!', '2009-08-13 14:45:52.000000', NULL, 1),
(5610480, 812533, 108697, '<td valign="top">I really enjoyed this photo and stared at it for a long time.  I wondred if you had exposed for slightly longer if the rain effect may have been more amplified by lookng more solid.I also wonderd what would have happened if you had used flash underexposing the background and highlighting the man.  Such a lovely scene for experimenting and lovely title.</td>', 'I really enjoyed this photo and stared at it for a long time.  I wondred if you had exposed for slightly longer if the rain effect may have been more amplified by lookng more solid.I also wonderd what would have happened if you had used flash underexposing the background and highlighting the man.  Such a lovely scene for experimenting and lovely title.', '2009-08-13 14:46:47.000000', NULL, 1),
(5610484, 813047, 108697, '<td valign="top">Not as scary as the book.  Liked the depth and the highlight of the dstant part of teh stream. The shadow on the left foreground I found a bit disconcerting</td>', 'Not as scary as the book.  Liked the depth and the highlight of the dstant part of teh stream. The shadow on the left foreground I found a bit disconcerting', '2009-08-13 14:49:21.000000', NULL, 1),
(5610487, 812790, 108697, '<td valign="top">Wow! The depth of field is great although.  The subject really popped out but I wonder if he had been a little more distant from the front if that may have had more effect.</td>', 'Wow! The depth of field is great although.  The subject really popped out but I wonder if he had been a little more distant from the front if that may have had more effect.', '2009-08-13 14:51:30.000000', NULL, 1),
(5610488, 812250, 81082, '<td valign="top">Love how I feel like the waves are rushing towards me!</td>', 'Love how I feel like the waves are rushing towards me!', '2009-08-13 14:51:48.000000', NULL, 1),
